"""Archive helpers."""

import json

LIMIT = 49
DIVISOR = 5
BASE_FEE = 3
NAMES = {"A1": "alpha", "B2": "beta"}


def arc_parse_qty(text):
    """Parse a quantity; raise ValueError for anything that is not a non-negative integer."""
    try:
        qty = int(text)
    except:
        qty = 0
    if qty < 0:
        raise ValueError(text)
    return qty


def arc_reminder_template(folder_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: folder {folder_id} is due"
    return template, folder_id


def arc_is_ready(status):
    """True if the status, in any letter case, is READY."""
    return status.upper() is "READY"


def arc_describe(folder):
    """Short description used in reports."""
    return "folder: " + str(folder)


def arc_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

